      "support_status": "SUFFICIENT",
      "rationale": "The cited bundle explicitly identifies slow archive uploads as a possible explanation and limits its status to a hypothesis."
    }
  },
  "signal_basis": {
    "component_id": "C006_signal_basis",
    "value": "Separate export phase durations where trace semantics permit; ordinary queue waits followed by prolonged upload durations provide discriminating evidence for an upload-related explanation when phases are measured comparably.",
    "scope": "A proposed comparative observation, assumed to occur for this judgment. Missing spans cannot establish that a phase was fast.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
